window.CROQUIS_DATA = [
  { id: 1,  title: 'Croquis 1 · Umbral de sombra y espera expectante', tag: 'Espera Locomoción', img: 'https://wiki-ead.b-cdn.net/images/7/70/Croqui_puerto_1.png', desc: 'Las personas se agrupan en el umbral de sombra que proyecta el edificio de la esquina, buscando refugio del viento mientras esperan la locomoción. La detención no es estática; el cuerpo se asoma intermitentemente hacia la calle, manteniendo una postura expectante que tensiona el límite entre la vereda y la calzada.' },
  { id: 2,  title: 'Croquis 2 · Congestión comercial Sotomayor × Blanco', tag: 'Borde Comercial', img: 'https://wiki-ead.b-cdn.net/images/f/f7/Croquis_puerto_2.png', desc: 'En la esquina de Sotomayor con Blanco se genera una gran congestión de personas, quienes permanecen cerca del local y consumen allí los productos que han comprado. Además, algunos conductores observan los carteles con la oferta de comida, se detienen para comprar y luego continúan su recorrido.' },
  { id: 3,  title: 'Croquis 3 · Descarga de buses, turistas, escolares y marinos', tag: 'Fricción Modal', img: 'https://wiki-ead.b-cdn.net/images/9/91/Croquis_puerto_3.png', desc: 'En la calle Sotomayor Blanco se genera un gran flujo de personas, debido a que los buses se detienen en esta vía, donde descienden turistas y escolares, además del tránsito constante de marinos.' },
  { id: 4,  title: 'Croquis 4 · Contemplación histórica vs. paso continuo', tag: 'Explanada Central', img: 'https://wiki-ead.b-cdn.net/images/c/c9/Croquis_puerto_4.jpg', desc: '«Mientras unos descubren la historia del lugar, otros simplemente lo atraviesan.» El movimiento se concentra en los bordes, donde la plaza se encuentra con el ritmo de la ciudad, creando una frontera dinámica entre quienes contemplan el espacio y el tránsito peatonal continuo.' },
  { id: 5,  title: 'Croquis 5 · Pausa de captura visual y fotografía', tag: 'Explanada Central', img: 'https://wiki-ead.b-cdn.net/images/0/0f/Croquis_puerto_5.jpg', desc: '«La plaza también se recorre con la mirada: algunos se detienen para llevarse una imagen del lugar.» La permanencia aquí no es de descanso, sino de captura visual. Quienes fotografían anclan su cuerpo momentáneamente, generando pausas estáticas dentro del flujo constante.' },
  { id: 6,  title: 'Croquis 6 · Esquina Sotomayor × Cochrane como embudo', tag: 'Cruce y Esquinas', img: 'https://wiki-ead.b-cdn.net/images/c/cf/Croquis_puerto_6.jpg', desc: '«La esquina se convierte en un umbral: la plaza se cruza, pero no necesariamente se habita.» Este vértice funciona como un embudo de paso obligado, evidenciando la fricción entre la velocidad de quien atraviesa y la ausencia de lugares que inviten a permanecer.' },
  { id: 7,  title: 'Croquis 7 · Sombras como refugio seguro para el celular', tag: 'Pausa Funcional', img: 'https://wiki-ead.b-cdn.net/images/2/20/CamScanner_07-10-2026_23.01_1.jpg', desc: '«Calle con sombras marcadas, las personas paran como "lugar seguro" para revisar su celular o como punto de encuentro con otras personas. ¿Cómo utilizan "mal" los espacios?»' },
  { id: 8,  title: 'Croquis 8 · Grupos grandes de escolares y percepción de seguridad', tag: 'Flujo Grupal', img: 'https://wiki-ead.b-cdn.net/images/1/18/CamScanner_07-10-2026_23.01_2.jpg', desc: '«Pasan grupos grandes de escolares. ¿Qué hace o tiene una calle para hacer sentir seguridad al transeúnte?»' },
  { id: 9,  title: 'Croquis 9 · Disposición lineal esperando la micro', tag: 'Espera Locomoción', img: 'https://wiki-ead.b-cdn.net/images/f/f9/CamScanner_08-10-26_00.30_1.jpg', desc: '«Las personas se distribuyen a lo largo de la vereda teniendo la locomoción entre sí, esperan la micro, observan alrededor.» La detención está condicionada por la espera del transporte, creando una disposición lineal a lo largo de la acera.' },
  { id: 10, title: 'Croquis 10 · Convergencia de tours guiados en el Monumento', tag: 'Explanada Central', img: 'https://wiki-ead.b-cdn.net/images/2/2e/CamScanner_08-10-26_00.30_2.jpg', desc: '«Grupos de turistas se detienen a observar la ciudad en un grupo grande, que anda con un guía. Se juntan en el centro de la plaza entre el monumento.» El espacio central se convierte en un punto de convergencia donde el recorrido se pausa.' },
  { id: 11, title: 'Croquis 11 · Ruptura de linealidad en el cruce de calles', tag: 'Cruce y Esquinas', img: 'https://wiki-ead.b-cdn.net/images/8/85/CamScanner_08-10-26_00.30_3.jpg', desc: '«La esquina parece un punto de detención, las personas se comportan distinto al llegar a este punto, miran, se detienen o permanecen en el lugar.» El cruce de calles rompe la linealidad del recorrido, obligando a una pausa.' },
  { id: 12, title: 'Croquis 12 · Fricción de velocidades entre grupos y solitarios', tag: 'Flujo Grupal', img: 'https://wiki-ead.b-cdn.net/images/8/88/CamScanner_08-10-26_00.30_4.JPG', desc: '«Esquina concurrida que reúne movimientos simultáneos, personas andan en grupo a menor velocidad que las personas que están solas.» La densidad de la esquina genera una fricción en los ritmos de caminata.' },
  { id: 13, title: 'Croquis 13 · La fachada como membrana de pausa breve', tag: 'Pausa Funcional', img: 'https://wiki-ead.b-cdn.net/images/2/25/PPBS_CROQUIS_M3_%281%29.jpeg', desc: 'El borde edificado actúa como una membrana de tránsito y detención breve. Mientras el flujo general avanza, surgen pausas individuales —como revisar el teléfono— que se adhieren a la fachada.' },
  { id: 14, title: 'Croquis 14 · El Monumento como núcleo de contemplación estática', tag: 'Explanada Central', img: 'https://wiki-ead.b-cdn.net/images/3/3b/PPBS_CROQUIS_M3_%282%29.jpeg', desc: 'La monumentalidad del hito central genera una pausa en el recorrido abierto. Las personas se congregan a los pies del monumento, transformando el centro de la explanada en un núcleo de contemplación estática.' },
  { id: 15, title: 'Croquis 15 · Apropiación bajo los toldos comerciales', tag: 'Borde Comercial', img: 'https://wiki-ead.b-cdn.net/images/8/87/Croquis_puerto_15.jpg', desc: 'La ocupación del espacio bajo los toldos comerciales. La estructura efímera provee una zona delimitada donde los peatones modifican su ritmo; las interacciones se vuelven frontales y la detención es un acto de apropiación del límite de la calzada.' },
  { id: 16, title: 'Croquis 16 · Cápsula de movimiento sincrónico grupal', tag: 'Flujo Grupal', img: 'https://wiki-ead.b-cdn.net/images/4/42/Croquis_puerto_16.jpg', desc: 'El tránsito grupal enmarca la marcha. Quienes caminan acompañados generan una cápsula de movimiento sincrónico, ocupando mayor ancho de vereda y adaptando su velocidad a la interacción interna del grupo.' },
  { id: 17, title: 'Croquis 17 · Capas de ocupación en el borde comercial', tag: 'Borde Comercial', img: 'https://wiki-ead.b-cdn.net/images/f/fe/Croquis_puerto_17.jpg', desc: 'La multiplicidad de acciones en el borde comercial. Mientras algunos se detienen a observar la oferta (focalización), otros utilizan la fachada como soporte para actividades individuales (revisar el teléfono), generando capas de ocupación peatonal.' },
  { id: 18, title: 'Croquis 18 · El semáforo como articulador mecánico del flujo', tag: 'Cruce y Esquinas', img: 'https://wiki-ead.b-cdn.net/images/d/dd/Croquis_puerto_18.jpg', desc: 'El semáforo como articulador del flujo. La señal de tránsito obliga a una detención mecánica de quienes intentan cruzar la calzada, acumulando personas en el vértice de la acera y creando una densificación temporal que se libera con el cambio de luz.' },
  { id: 19, title: 'Croquis 19 · El quiosco como mobiliario urbano improvisado', tag: 'Borde Comercial', img: 'https://wiki-ead.b-cdn.net/images/5/54/Croquis_puerto_19.jpg', desc: 'El toldo o quiosco como hito de detención. Las personas no solo compran o transitan, sino que se apoyan en la estructura, utilizándola como mobiliario urbano improvisado para establecer conversaciones prolongadas.' },
  { id: 20, title: 'Croquis 20 · Conflicto visual entre comercio ambulante y vehículos', tag: 'Fricción Modal', img: 'https://wiki-ead.b-cdn.net/images/a/a4/Croquis_puerto_20.jpg', desc: 'El conflicto visual entre el comercio ambulante y el flujo vehicular. El tránsito peatonal se ve condicionado por los obstáculos visuales (como los letreros de confites) a la vez que negocia el espacio de cruce con la proximidad.' }
];

